1	package scan
2	
3	import (
4		"log"
5		"os"
6		"path/filepath"
7		"regexp"
8		"strings"
9	
10		"github.com/anthnel/devdesk/internal/k8s"
11	)
12	
13	// Why a KSV-0104 finding fired (DEVDESK-686, S-01). Trivy words the finding the
14	// same for an explicit Unconfined and for a missing seccomp profile, and
15	// points at the container's block rather than at the line that says
16	// Unconfined, so neither the message nor the span tells the two apart. The
17	// manifest is read again at scan time, the way the Kubernetes fixes read it
18	// (§3.80): the document at the reported line, the container by its name inside
19	// the reported lines.
20	const (
21		SeccompUnconfined = "unconfined"
22		SeccompAbsent     = "absent"
23	)
24	
25	// seccompContainer is how KSV-0104 names its container: lower case and double
26	// quotes, unlike the other KSV rules ("Container 'api' of …").
27	var seccompContainer = regexp.MustCompile(`container "([^"]+)"`)
28	
29	// isSeccompRule reports whether id is KSV-0104, in any of the three spellings
30	// Trivy and the cache have used. This package cannot import remediation, where
31	// RuleKey lives.
32	func isSeccompRule(id string) bool {
33		id = strings.ReplaceAll(strings.TrimPrefix(strings.ToUpper(strings.TrimSpace(id)), "AVD-"), "-", "")
34		return id == "KSV0104" || id == "KSV104"
35	}
36	
37	// annotateSeccomp sets SeccompOrigin on the kubernetes KSV-0104 findings of a
38	// directory scan, reading each file once. It never fails the scan: whatever it
39	// cannot confirm leaves the origin empty, which reads as "unknown".
40	func annotateSeccomp(root string, findings []Finding) {
41		byFile := map[string][]int{}
42		for i, f := range findings {
43			if f.Source == SourceTrivyMisconfig && f.IaCType == "kubernetes" && isSeccompRule(f.ID) {
44				byFile[f.File] = append(byFile[f.File], i)
45			}
46		}
47		if len(byFile) == 0 {
48			return
49		}
50		dir, err := os.OpenRoot(root)
51		if err != nil {
52			log.Printf("WARN [scan] seccomp origin: cannot open %s: %v", root, err)
53			return
54		}
55		defer func() { _ = dir.Close() }()
56	
57		for file, indexes := range byFile {
58			name := filepath.FromSlash(file)
59			if !filepath.IsLocal(name) {
60				log.Printf("WARN [scan] seccomp origin: %s is outside the scanned directory", file)
61				continue
62			}
63			content, err := k8s.ReadManifestIn(dir, name)
64			if err != nil {
65				log.Printf("WARN [scan] seccomp origin: cannot read %s: %v", file, err)
66				continue
67			}
68			for _, i := range indexes {
69				findings[i].SeccompOrigin = seccompOrigin(content, findings[i])
70			}
71		}
72	}
73	
74	// seccompOrigin classifies one KSV-0104 finding from the manifest's bytes:
75	// SeccompUnconfined, SeccompAbsent, or "" when it cannot tell (the file
76	// changed since Trivy read it, the container is not at the reported lines, a
77	// profile is now set).
78	func seccompOrigin(content []byte, f Finding) string {
79		m := seccompContainer.FindStringSubmatch(f.Message)
80		if m == nil || f.Line <= 0 {
81			return ""
82		}
83		doc, ok := k8s.DocumentAt(content, f.Line)
84		if !ok {
85			return ""
86		}
87		for _, spec := range k8s.PodSpecs(doc) {
88			for _, c := range spec.Containers {
89				if k8s.Scalar(c, "name") != m[1] {
90					continue
91				}
92				if f.EndLine > 0 && (c.Line < f.Line || c.Line > f.EndLine) {
93					continue
94				}
95				switch t := k8s.SeccompType(doc, spec, c); {
96				case strings.EqualFold(t, "unconfined"):
97					return SeccompUnconfined
98				case t == "":
99					return SeccompAbsent
100				}
101				return ""
102			}
103		}
104		return ""
105	}
106

